    byHand: "The volume is πr^2h = 245π, so r^2h = 245, and the lateral area is 2πrh = 70π, so rh = 35. Dividing r^2h = 245 by rh = 35 yields r = 7. Therefore, the radius of the cylinder is 7 units (and its height is 35/7 = 5 units). Alternate approach: the ratio of the volume to the lateral area is πr^2h/(2πrh) = r/2, so r/2 = 245/70 = 3.5 and r = 7. A common slip is to use rh = 70, leaving out the 2 in the lateral area, which gives r = 3.5.",
